css:
.rsr-root[data-theme='flat'] .container { width: auto; max-width: 706px; margin: 0 auto; padding: 0; }
.rsr-root[data-theme='flat'] .row { margin: 0; }
.rsr-root[data-theme='flat'] .row::after { content: ""; display: table; clear: both; }
.rsr-root[data-theme='flat'] .col-sm-3 { width: 25%; float: left; }
.rsr-root[data-theme='flat'] .col-sm-9 { width: 75%; float: left; }
.rsr-root[data-theme='flat'] .col-sm-6 { width: 50%; float: left; }
.rsr-root[data-theme='flat'] .col-sm-12 { width: 100%; float: left; }
.rsr-root[data-theme='flat'] .col-sm-push-3 { margin-left: 25%; }
.rsr-root[data-theme='flat'] .pull-right { float: right; }
.rsr-root[data-theme='flat'] #header { margin: -42px -46px 0; padding: 30px 46px 6px; }
.rsr-root[data-theme='flat'] .keywords { line-height: 1.8; }

.rsr-root[data-theme='flat'] {background: #fff;
	font-family: Lato, sans-serif;
	margin: 0 0 80px; }
.rsr-root[data-theme='flat'] a {color: #2ecc71; }
.rsr-root[data-theme='flat'] a:focus, .rsr-root[data-theme='flat'] a:hover {color: #f1c40f;
	text-decoration: none; }
.rsr-root[data-theme='flat'] p {line-height: 1.5;
	margin: 0; }
.rsr-root[data-theme='flat'] p + p {margin-top: 10px; }
.rsr-root[data-theme='flat'] h1, .rsr-root[data-theme='flat'] h2, .rsr-root[data-theme='flat'] h3, .rsr-root[data-theme='flat'] h4 {margin-top: 0 }
.rsr-root[data-theme='flat'] section {margin-top: 30px; }
.rsr-root[data-theme='flat'] li {line-height: 1.8;
	list-style: none; }
.rsr-root[data-theme='flat'] li:before {content: "\f052";
	float: left;
	font: 13px Octicons;
	margin-top: 6px;
	margin-left: -20px;
	opacity: .1;
	position: absolute; }
.rsr-root[data-theme='flat'] blockquote {border-left: 5px solid #e7e9ec;
	font-size: 14px; }
.rsr-root[data-theme='flat'] em {color: #95a5a6;
	font-weight: normal;
	font-style: normal; }
.rsr-root[data-theme='flat'] h4 span:first-child {color: #000;
	font-weight: bold; }
.rsr-root[data-theme='flat'] .container {max-width: 750px;
	padding: 0 30px; }
.rsr-root[data-theme='flat'] .col-sm-6 {margin-bottom: 10px; }
.rsr-root[data-theme='flat'] .col-sm-12 h4 {margin-top: 12px; }
.rsr-root[data-theme='flat'] .col-sm-12 + .col-sm-12 {margin-top: 30px; }
.rsr-root[data-theme='flat'] #header {background: #f4f6f6;
	padding: 50px 0;
	margin-bottom: 30px; }
.rsr-root[data-theme='flat'] #header h2 {color: #95a5a6;
	font-size: 24px; }
.rsr-root[data-theme='flat'] #content h3 {color: #f1c40f;
	font-size: 26px;
	margin-top: -4px; }
.rsr-root[data-theme='flat'] #content aside {text-align: right;
	padding-right: 30px; }
.rsr-root[data-theme='flat'] #profiles .network {text-transform: capitalize; }
.rsr-root[data-theme='flat'] #work .position, .rsr-root[data-theme='flat'] #volunteer .position {font-weight: bold;
	margin-bottom: 8px; }
.rsr-root[data-theme='flat'] #education .area {font-weight: bold; }
.rsr-root[data-theme='flat'] #education .area:before {content: "\f0d7";
	font: 16px Octicons;
	margin-right: 6px; }
.rsr-root[data-theme='flat'] #education .studyType {margin-left: 25px; }
.rsr-root[data-theme='flat'] #awards .summary, .rsr-root[data-theme='flat'] #publications .summary {margin-top: 8px; }
.rsr-root[data-theme='flat'] #publications .website a:before {content: attr(href); }
